$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest

$root = (Get-Location).Path
if (-not (Test-Path (Join-Path $root 'pubspec.yaml'))) {
    throw 'Run this script from the almustafa-connect-erp project root.'
}

$utf8 = New-Object System.Text.UTF8Encoding($false)
$stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
$backupRoot = Join-Path (Split-Path $root -Parent) "almustafa-connect-erp_backups/fee_phase6_reports_parent_$stamp"

function Read-ProjectFile {
    param([Parameter(Mandatory = $true)][string]$RelativePath)
    $path = Join-Path $root $RelativePath
    if (-not (Test-Path $path)) {
        throw "Required file not found: $RelativePath"
    }
    return [IO.File]::ReadAllText($path).Replace("`r`n", "`n")
}

function Write-ProjectFile {
    param(
        [Parameter(Mandatory = $true)][string]$RelativePath,
        [Parameter(Mandatory = $true)][string]$Content
    )

    $path = Join-Path $root $RelativePath
    New-Item -ItemType Directory -Path (Split-Path $path -Parent) -Force | Out-Null
    [IO.File]::WriteAllText($path, $Content, $utf8)
    Write-Host "Created/updated: $RelativePath" -ForegroundColor Green
}

function Backup-ProjectFile {
    param([Parameter(Mandatory = $true)][string]$RelativePath)
    $source = Join-Path $root $RelativePath
    if (-not (Test-Path $source)) { return }
    $destination = Join-Path $backupRoot $RelativePath
    New-Item -ItemType Directory -Path (Split-Path $destination -Parent) -Force | Out-Null
    Copy-Item $source $destination -Force
}

function Ensure-BeforeAnchor {
    param(
        [Parameter(Mandatory = $true)][string]$Content,
        [Parameter(Mandatory = $true)][string]$UniqueMarker,
        [Parameter(Mandatory = $true)][string]$Anchor,
        [Parameter(Mandatory = $true)][string]$Block
    )

    if ($Content.Contains($UniqueMarker)) { return $Content }
    $index = $Content.IndexOf($Anchor)
    if ($index -lt 0) { throw "Integration anchor not found: $Anchor" }
    return $Content.Substring(0, $index) + $Block + $Content.Substring($index)
}

$payloads = @{
    'lib/features/fees/domain/entities/fee_report_entity.dart' = ''
    'lib/features/fees/domain/services/fee_report_service.dart' = ''
    'lib/features/fees/data/services/fee_report_service_impl.dart' = ''
    'lib/features/fees/presentation/bloc/fee_reports_bloc.dart' = ''
    'lib/features/fees/presentation/pages/fee_reports_page.dart' = ''
    'lib/features/fees/presentation/pages/parent_fee_portal_page.dart' = ''
}
$serviceLocator = 'lib/core/di/service_locator.dart'
$dashboard = 'lib/features/fees/presentation/pages/fee_management_dashboard_page.dart'

foreach ($relativePath in (@($serviceLocator, $dashboard) + $payloads.Keys)) {
    Backup-ProjectFile -RelativePath $relativePath
}

foreach ($item in $payloads.GetEnumerator()) {
    $text = [Text.Encoding]::UTF8.GetString(
        [Convert]::FromBase64String($item.Value)
    )
    Write-ProjectFile -RelativePath $item.Key -Content $text
}

$content = Read-ProjectFile -RelativePath $serviceLocator

$content = Ensure-BeforeAnchor `
    -Content $content `
    -UniqueMarker 'fee_report_service_impl.dart' `
    -Anchor "import '../../features/fees/data/services/fee_document_service_impl.dart';" `
    -Block "import '../../features/fees/data/services/fee_report_service_impl.dart';`n"

$content = Ensure-BeforeAnchor `
    -Content $content `
    -UniqueMarker 'fee_report_service.dart' `
    -Anchor "import '../../features/fees/domain/services/fee_document_service.dart';" `
    -Block "import '../../features/fees/domain/services/fee_report_service.dart';`n"

$content = Ensure-BeforeAnchor `
    -Content $content `
    -UniqueMarker 'fee_reports_bloc.dart' `
    -Anchor "import '../../features/fees/presentation/bloc/fee_document_bloc.dart';" `
    -Block "import '../../features/fees/presentation/bloc/fee_reports_bloc.dart';`n"

$serviceRegistration = @'
  sl.registerLazySingleton<FeeReportService>(
    FeeReportServiceImpl.new,
  );

'@

$content = Ensure-BeforeAnchor `
    -Content $content `
    -UniqueMarker 'registerLazySingleton<FeeReportService>' `
    -Anchor '  sl.registerLazySingleton<FeeDocumentService>(' `
    -Block $serviceRegistration

$blocRegistration = @'
  sl.registerFactory<FeeReportsBloc>(
    () => FeeReportsBloc(
      sl<MonthlyFeeDueRepository>(),
      sl<FeePaymentRepository>(),
      sl<FeeReportService>(),
    ),
  );

'@

$content = Ensure-BeforeAnchor `
    -Content $content `
    -UniqueMarker 'registerFactory<FeeReportsBloc>' `
    -Anchor '  sl.registerFactory<FeeDocumentBloc>(' `
    -Block $blocRegistration

Write-ProjectFile -RelativePath $serviceLocator -Content $content

$content = Read-ProjectFile -RelativePath $dashboard

$content = Ensure-BeforeAnchor `
    -Content $content `
    -UniqueMarker "import 'fee_reports_page.dart';" `
    -Anchor "import 'fee_structure_page.dart';" `
    -Block "import 'fee_reports_page.dart';`n"

$oldAction = "        onTap: () => _comingSoon(context, 'Fee Reports'),"

$newAction = @'
        onTap: () {
          Navigator.of(context).push(
            MaterialPageRoute<void>(
              builder: (_) => const FeeReportsPage(),
            ),
          );
        },
'@

if ($content.Contains($oldAction)) {
    $content = $content.Replace($oldAction, $newAction)
} elseif (-not $content.Contains('const FeeReportsPage()')) {
    throw 'Could not locate Fee Reports dashboard action.'
}

Write-ProjectFile -RelativePath $dashboard -Content $content

$formatFiles = @($serviceLocator, $dashboard) + $payloads.Keys

Write-Host ''
Write-Host 'Running dart format...' -ForegroundColor Cyan
& dart format $formatFiles
if ($LASTEXITCODE -ne 0) {
    throw 'dart format failed.'
}

Write-Host ''
Write-Host 'Running flutter analyze...' -ForegroundColor Cyan
& flutter analyze
if ($LASTEXITCODE -ne 0) {
    throw 'flutter analyze found issues. Copy the complete output into ChatGPT.'
}

Write-Host ''
Write-Host 'Fee Management Phase 6 Reports and Parent Portal completed successfully.' -ForegroundColor Green
Write-Host 'Fee Management module is now ready to freeze after final QA.' -ForegroundColor Cyan
Write-Host "Backup: $backupRoot" -ForegroundColor DarkGray
